// Package emoji is the emoji the client's picker offers: Unicode's set in
// its own order and groups, with names, search keywords, GitHub
// :shortcodes: and skin tones. The table is generated by tools/emojigen.
package emoji

import (
	"sort"
	"strings"
	"sync"
)

// Emoji is one emoji the picker offers.
type Emoji struct {
	Char       string   // "👍"
	Name       string   // "thumbs up"
	Group      int      // index into GroupNames
	Shortcodes []string // GitHub's, without colons: "+1", "thumbsup"
	Keywords   []string // CLDR's: "hand", "thumb", "up"
	Tones      []string // skin-tone versions, light to dark; nil if it has none
}

// WithTone is e in skin tone t (1 light ... 5 dark), or as it is for 0 or
// an emoji without tones.
func (e *Emoji) WithTone(t int) string {
	if t < 1 || t > len(e.Tones) {
		return e.Char
	}
	return e.Tones[t-1]
}

var (
	load    sync.Once
	all     []*Emoji
	byChar  map[string]*Emoji
	byShort map[string]*Emoji
)

func parse() {
	byChar, byShort = map[string]*Emoji{}, map[string]*Emoji{}
	for _, line := range strings.Split(strings.TrimSuffix(table, "\n"), "\n") {
		f := strings.Split(line, "\t")
		if len(f) != 6 {
			continue
		}
		e := &Emoji{Char: f[0], Name: f[2], Shortcodes: strings.Fields(f[3]), Tones: strings.Fields(f[5])}
		e.Group = int(f[1][0] - '0')
		if f[4] != "" {
			e.Keywords = strings.Split(f[4], "|")
		}
		all = append(all, e)
		byChar[e.Char] = e
		byChar[strings.ReplaceAll(e.Char, "️", "")] = e
		for _, t := range e.Tones {
			byChar[t] = e
		}
		for _, s := range e.Shortcodes {
			byShort[s] = e
		}
	}
}

// All is every emoji, in Unicode's order.
func All() []*Emoji {
	load.Do(parse)
	return all
}

// Lookup finds the emoji s is (or a skin-tone version of).
func Lookup(s string) (*Emoji, bool) {
	load.Do(parse)
	e, ok := byChar[s]
	if !ok {
		e, ok = byChar[strings.ReplaceAll(s, "️", "")]
	}
	return e, ok
}

// Shortcode finds an emoji by a GitHub shortcode, with or without colons.
func Shortcode(code string) (*Emoji, bool) {
	load.Do(parse)
	e, ok := byShort[strings.ToLower(strings.Trim(code, ":"))]
	return e, ok
}

// Search finds emoji for what someone typed ("thumbs", "party", ":grap"),
// best first: a shortcode or name that is the query, then ones that start
// with it, then names and keywords with a word that starts with it, then
// any that contain it. Every word of a multi-word query must match. At
// most limit results (0: all).
func Search(query string, limit int) []*Emoji {
	load.Do(parse)
	words := strings.Fields(strings.ToLower(strings.Trim(strings.TrimSpace(query), ":")))
	if len(words) == 0 {
		return nil
	}
	type hit struct {
		e     *Emoji
		score int
		order int
	}
	var hits []hit
	for i, e := range all {
		total := 0
		for _, w := range words {
			s := score(e, w)
			if s == 0 {
				total = 0
				break
			}
			total += s
		}
		if total > 0 {
			hits = append(hits, hit{e, total, i})
		}
	}
	sort.SliceStable(hits, func(i, j int) bool {
		if hits[i].score != hits[j].score {
			return hits[i].score > hits[j].score
		}
		return hits[i].order < hits[j].order
	})
	if limit > 0 && len(hits) > limit {
		hits = hits[:limit]
	}
	out := make([]*Emoji, len(hits))
	for i, h := range hits {
		out[i] = h.e
	}
	return out
}

// score is how well one query word matches e (0: not at all).
func score(e *Emoji, w string) int {
	name := strings.ToLower(e.Name)
	best := 0
	up := func(s int) {
		if s > best {
			best = s
		}
	}
	for _, s := range e.Shortcodes {
		switch {
		case s == w:
			up(100)
		case strings.HasPrefix(s, w):
			up(60)
		}
	}
	switch {
	case name == w:
		up(100)
	case strings.HasPrefix(name, w):
		up(70)
	}
	for _, part := range strings.FieldsFunc(name, func(r rune) bool { return r == ' ' || r == ':' || r == ',' || r == '-' }) {
		switch {
		case part == w:
			up(50)
		case strings.HasPrefix(part, w):
			up(40)
		}
	}
	for _, k := range e.Keywords {
		switch {
		case k == w:
			up(35)
		case strings.HasPrefix(k, w):
			up(25)
		}
	}
	if best == 0 && len(w) >= 3 && strings.Contains(name, w) {
		up(10)
	}
	return best
}
